/** @return never */
function out(array $lines, int $status=200): never { http_response_code($status); echo implode("\n",$lines),"\n"; exit; }
function kclString(string $value, int $maxLen=500): string {
    $value=trim($value); if(kicomTextLen($value)>$maxLen)$value=kicomTextSubstr($value,0,$maxLen);
    $value=str_replace(["\\","\r","\n","\t",'"'],["\\\\","\\r","\\n","\\t",'\\"'],$value);
    return '"'.$value.'"';
}
function requireGetMutationIntent(string $operation,string $target,string $rid): void {
