    $r=kicomConsumeIntent($token,$operation,$target);
    if(!$r['ok']) out([KCL_PROTOCOL,'ERROR mutation_guard','FACT request_id='.kclString($rid),'FACT code='.kclString((string)$r['code']),'FACT operation='.kclString($operation),'FACT target='.kclString($target),'REQUIRES bridge_intent=true','LINK intent="?q=BRIDGE_INTENT&operation='.$operation.'&target='.rawurlencode($target).'"','LINK post_api="api.php"','END'],428);
}
/** @return never */
function outMemory(string $name,string $rid): never {
    $res=kicomReadMemoryResource($name);
    if($res===null) out([KCL_PROTOCOL,'ERROR memory','FACT request_id='.kclString($rid),'FACT code="MEMORY_RESOURCE_UNAVAILABLE"','FACT resource='.kclString($name),'END'],503);
